136	    /**
137	     * Look up the owner identified by {@code ownerId} and, when it exists, produce the response with
138	     * {@code onFound}; when no such owner exists, short-circuit with {@code 404 NOT_FOUND}. Centralizes
139	     * the fetch-and-guard shared by the single-owner endpoints so it is written once, not copied.
140	     */
141	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> onFound) {
142	        Owner owner = this.clinicService.findOwnerById(ownerId);
143	        if (owner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        return onFound.apply(owner);
147	    }
