149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
152	        String idempotencyKey = currentIdempotencyKey();
153	        if (idempotencyKey != null) {
154	            Integer existingId = idempotentCreates.get(idempotencyKey);
155	            if (existingId != null) {
156	                Owner existing = this.clinicService.findOwnerById(existingId);
157	                if (existing != null) {
158	                    return new ResponseEntity<>(buildOwnerDto(existing), HttpStatus.OK);
159	                }
160	            }
161	        }
162	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
163	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
164	                && response.getBody() != null && response.getBody().getId() != null) {
165	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
166	        }
167	        return response;
168	    }
169	
170	    /**
171	     * The non-blank {@code Idempotency-Key} header on the current request, or {@code null} when the
172	     * header is absent or blank. Read from the ambient request rather than the handler signature so the
173	     * generated {@link OwnersApi#addOwner} contract stays unchanged.
174	     */
175	    private static String currentIdempotencyKey() {
176	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs) {
177	            String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
178	            if (key != null && !key.isBlank()) {
179	                return key;
180	            }
181	        }
182	        return null;
183	    }
