185	    /**
186	     * Run the create pipeline for a new owner from its submitted fields and return the response: the
187	     * fields are mapped, normalized and validated, the registration date is resolved, the per-day,
188	     * identity and per-city gates are applied, the derived registration attributes are
189	     * assigned and the owner is saved and audited, yielding {@code 201 CREATED} with the new owner and
190	     * its {@code Location}. A gate that trips short-circuits with its own status ({@code 400},
191	     * {@code 429} or {@code 409}) and no owner is created. This is the single place an owner is created;
192	     * {@link #addOwner} is the thin entry point that delegates here, so request-level concerns stay out
193	     * of the create pipeline.
194	     */
195	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
196	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
197	        if (!normalizeAndValidateFields(owner)) {
198	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
199	        }
200	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
201	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
202	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
203	        }
204	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
205	        owner.setRegistrationDate(registrationDate);
206	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
207	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
208	        }
209	        owner.setHouseholdId(householdId(owner));
210	        owner.setIdentityKey(identityKey(owner));
211	        if (isDuplicate(owner)) {
212	            return new ResponseEntity<>(HttpStatus.CONFLICT);
213	        }
214	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
215	        if (countOwnersInCity(owner.getCity()) >= 50) {
216	            return new ResponseEntity<>(HttpStatus.CONFLICT);
217	        }
218	        assignRegistrationAttributes(owner, sharesHousehold);
219	        this.clinicService.saveOwner(owner);
220	        auditOwnerCreated(owner);
221	        enqueueWelcomeNotification(owner);
222	        HttpHeaders headers = new HttpHeaders();
223	        headers.setLocation(UriComponentsBuilder.newInstance()
224	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
225	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
226	    }
227	
228	    /**
229	     * Emit the audit trail for a freshly persisted {@code owner} on the dedicated {@code AUDIT}
230	     * logger: the human-readable line followed by the structured {@link OwnerCreatedEvent}. This is
231	     * the one place a created owner's identifiers are read for the audit trail, so a change to which
232	     * identifier is audited is confined here rather than woven through the create pipeline.
233	     */
234	    private void auditOwnerCreated(Owner owner) {
235	        AUDIT.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
236	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
237	        AUDIT.info(OwnerCreatedEvent.of(AUDIT_EVENT_SEQ.incrementAndGet(), owner).toJson());
238	    }
239	
240	    /**
241	     * Enqueue the welcome notification for a freshly persisted {@code owner} on the dedicated
242	     * {@code NOTIFY} logger: one line carrying the owner's id and member id, the identifiers a
243	     * downstream notifier needs to greet the new member. Kept separate from the audit trail so the
244	     * notification concern is emitted in one place, after the owner is saved and its id is assigned.
245	     */
246	    private void enqueueWelcomeNotification(Owner owner) {
247	        NOTIFY.info("Welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
248	    }
249	
250	    /**
251	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
252	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
253	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
254	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
255	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
256	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
257	     */
258	    private boolean normalizeAndValidateFields(Owner owner) {
259	        if (!normalizeAddressFields(owner)) {
260	            return false;
261	        }
262	        if (owner.getEmail() != null) {
263	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
264	            if (!EMAIL_PATTERN.matcher(email).matches()) {
265	                return false;
266	            }
267	            if (isDisposableEmailDomain(email)) {
268	                return false;
269	            }
270	            owner.setEmail(email);
271	        }
272	        if (!isPostcodeValidForCity(owner)) {
273	            return false;
274	        }
275	        String telephone = normalizeTelephone(owner.getTelephone());
276	        if (telephone == null) {
277	            return false;
278	        }
279	        owner.setTelephone(telephone);
280	        return true;
281	    }
282	
283	    /**
284	     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
285	     * returning whether the owner may proceed to creation. The structured fields are preferred when
286	     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
287	     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
288	     * composed value (the normalized addressLine1, with a single space and the normalized
289	     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
290	     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
291	     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
292	     * address. This is the single place the owner's address is read, canonicalized and written back,
293	     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
294	     */
295	    private boolean normalizeAddressFields(Owner owner) {
296	        String line1 = normalizeAddress(owner.getAddressLine1());
297	        if (!line1.isEmpty()) {
298	            String line2 = normalizeAddress(owner.getAddressLine2());
299	            owner.setAddressLine1(line1);
300	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
301	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
302	            return true;
303	        }
304	        String address = normalizeAddress(owner.getAddress());
305	        if (address.isEmpty()) {
306	            return false;
307	        }
308	        owner.setAddress(address);
309	        return true;
310	    }
311	
312	    /**
313	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
314	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
315	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
316	     */
317	    private static boolean isDisposableEmailDomain(String email) {
318	        int at = email.lastIndexOf('@');
319	        if (at < 0) {
320	            return false;
321	        }
322	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
323	    }
324	
325	    /**
326	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
327	     * computed against the owner population rather than carried on the owner itself (currently the
328	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
329	     * listing intentionally omits these flags.
330	     */
331	    private OwnerDto buildOwnerDto(Owner owner) {
332	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
333	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
334	        ownerDto.setCapacityWarning(isCapacityWarning(owner));
335	        return ownerDto;
336	    }
337	
338	    /**
339	     * Whether {@code owner}'s city is approaching its per-city capacity limit: it already holds between
340	     * 40 and 49 other owners, one short of the hard limit of 50 at which creation is rejected.
341	     * Surfaced on responses as {@code capacityWarning}. Computed against the current owner population
342	     * excluding this owner, so the count basis mirrors the per-city create gate (which counts the
343	     * owners already present, before the new one is added).
344	     */
345	    private boolean isCapacityWarning(Owner owner) {
346	        long othersInCity = countOtherOwnersInCity(owner);
347	        return othersInCity >= 40 && othersInCity < 50;
348	    }
