350	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
351	    @Override
352	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
353	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
354	        if (currentOwner == null) {
355	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
356	        }
357	        currentOwner.setAddress(ownerFieldsDto.getAddress());
358	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
359	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
360	        currentOwner.setCity(ownerFieldsDto.getCity());
361	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
362	        currentOwner.setLastName(ownerFieldsDto.getLastName());
363	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
364	        String email = ownerFieldsDto.getEmail();
365	        if (email != null) {
366	            email = email.trim().toLowerCase(Locale.ROOT);
367	            if (!EMAIL_PATTERN.matcher(email).matches()) {
368	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
369	            }
370	        }
371	        currentOwner.setEmail(email);
372	        this.clinicService.saveOwner(currentOwner);
373	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
374	    }
