452	    /** Matches a well-formed postcode: exactly 4 digits. */
453	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
454	
455	    /**
456	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
457	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
458	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
459	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
460	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
461	     */
462	    private static boolean isPostcodeValidForCity(Owner owner) {
463	        String postcode = owner.getPostcode();
464	        if (postcode == null) {
465	            return true;
466	        }
467	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
468	            return false;
469	        }
470	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
471	        if (range == null) {
472	            return true;
473	        }
474	        int value = Integer.parseInt(postcode);
475	        return value >= range[0] && value <= range[1];
476	    }
477	
478	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
479	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
480	
481	    /**
482	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
483	     * code are kept when present; otherwise country code '+61' is assumed and a single
484	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
485	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
486	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
487	     * Returns {@code null} when the number cannot form a valid E.164 value.
488	     */
489	    private static String normalizeTelephone(String telephone) {
490	        if (telephone == null) {
491	            return null;
492	        }
493	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
494	        String e164;
495	        if (cleaned.startsWith("+")) {
496	            e164 = cleaned;
497	        } else {
498	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
499	            e164 = "+61" + national;
500	        }
501	        if (!E164_PATTERN.matcher(e164).matches()) {
502	            return null;
503	        }
504	        return hasValidNationalNumberLength(e164) ? e164 : null;
505	    }
506	
507	    /**
508	     * Whether the national number of a well-formed E.164 value has the length required for its
509	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
510	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
511	     */
512	    private static boolean hasValidNationalNumberLength(String e164) {
513	        String countryCode = Owner.countryCodeOf(e164);
514	        if (countryCode == null) {
515	            return true;
516	        }
517	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
518	    }
519	
520	    /**
521	     * Compute and assign the derived attributes carried by a newly registered owner: the member id,
522	     * household id, namesake count and household member count. Each is derived from the owner's
523	     * already-normalized fields and the existing owner population, so this must run before the owner
524	     * is saved, while the counts still exclude the owner being created.
525	     *
526	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
527	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
528	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
529	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
530	     */
531	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
532	        owner.setMemberId(generateMemberId(owner));
533	        owner.setHouseholdId(householdId(owner));
534	        owner.setNamesakeCount(countNamesakes(owner));
535	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
536	        owner.setMembershipLevelCap(membershipLevelCapForHousehold(owner));
537	        if (declaredMember) {
538	            owner.setPossibleDuplicate(false);
539	            owner.setPossibleDuplicateOf(null);
540	        } else {
541	            assignPossibleDuplicate(owner);
542	        }
543	    }
544	
545	    /**
546	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
547	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's postcode
548	     * and last-name {@link #soundex(String) Soundex} yet resolves to a different {@link #identityKey}.
549	     * Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf} to the
550	     * matching owner's id. Runs before save, against the existing owner population.
551	     */
552	    private void assignPossibleDuplicate(Owner owner) {
553	        Integer matchId = findPossibleDuplicateOf(owner);
554	        owner.setPossibleDuplicate(matchId != null);
555	        owner.setPossibleDuplicateOf(matchId);
556	    }
557	
558	    /**
559	     * The id of an existing owner that shares {@code owner}'s postcode and last-name
560	     * {@link #soundex(String) Soundex} but resolves to a different {@link #identityKey}, or
561	     * {@code null} when there is none. Because the telephone is part of the identity key, two owners
562	     * with the same last name and postcode but different telephones differ in key and so match here,
563	     * making the later a soft (possible) duplicate rather than a hard conflict. When several match,
564	     * the lowest id is returned. An owner without a postcode never matches.
565	     */
566	    private Integer findPossibleDuplicateOf(Owner owner) {
567	        String postcode = owner.getPostcode();
568	        if (postcode == null) {
569	            return null;
570	        }
571	        String soundex = soundex(owner.getLastName());
572	        String identityKey = owner.getIdentityKey();
573	        return this.clinicService.findAllOwners().stream()
574	            .filter(existing -> !existing.isDeleted())
575	            .filter(existing -> existing.getId() != null
576	                && postcode.equals(existing.getPostcode())
577	                && soundex(existing.getLastName()).equals(soundex)
578	                && !identityKey.equals(existing.getIdentityKey()))
579	            .map(Owner::getId)
580	            .min(Integer::compareTo)
581	            .orElse(null);
582	    }
583	
584	    /**
585	     * Build {@code owner}'s member id '<REGION><FY><HASH8><CHK>': REGION is the region code derived
586	     * from the owner's postcode ({@link Owner#getRegion()}), FY the two-digit
587	     * {@link Owner#fiscalYearSegment(LocalDate) fiscal-year segment} of the business-day-adjusted
588	     * {@link Owner#getRegistrationDate() registration date}, HASH8 the first 8 upper-case hex
589	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
590	     * owner's last name, and CHK a single {@link Owner#luhnCheckDigit(String) Luhn check digit} over
591	     * the digits of '<REGION><FY><HASH8>' (e.g. 'NSW271A2B3C4D5'). The identity is otherwise a pure
592	     * function of the region, fiscal year and the (telephone, last name) pair; only when the computed
593	     * id collides with an existing owner's member id is it de-duplicated by appending '-<n>' with the
594	     * smallest {@code n} of 2 or more that makes it unique (e.g. 'NSW271A2B3C4D5-2').
595	     */
596	    private String generateMemberId(Owner owner) {
597	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
598	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
599	        String hash8 = Owner.sha256Hex(telephone + lastName).substring(0, 8);
600	        String core = owner.getRegion() + Owner.fiscalYearSegment(owner.getRegistrationDate()) + hash8;
601	        String base = core + Owner.luhnCheckDigit(core);
602	        return deduplicateMemberId(base);
603	    }
604	
605	    /**
606	     * De-duplicate a computed member id against the existing owner population: when {@code base}
607	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
608	     * {@code n} of 2 or more that yields an id no existing owner carries.
609	     */
610	    private String deduplicateMemberId(String base) {
611	        Set<String> existing = this.clinicService.findAllOwners().stream()
612	            .map(Owner::getMemberId)
613	            .filter(code -> code != null)
614	            .collect(java.util.stream.Collectors.toSet());
615	        if (!existing.contains(base)) {
616	            return base;
617	        }
618	        int n = 2;
619	        while (existing.contains(base + "-" + n)) {
620	            n++;
621	        }
622	        return base + "-" + n;
623	    }
624	
625	    /**
626	     * The number of existing owners registered in {@code city}, compared case-insensitively
627	     * with collapsed whitespace.
628	     */
629	    private int countOwnersInCity(String city) {
630	        String normalized = normalizeHouseholdField(city);
631	        return (int) this.clinicService.findAllOwners().stream()
632	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
633	            .count();
634	    }
635	
636	    /**
637	     * The number of existing owners in {@code owner}'s city other than {@code owner} itself, compared
638	     * case-insensitively with collapsed whitespace. This is the count of owners already present in the
639	     * city that a newly created owner joins, mirroring the basis of the per-city create gate.
640	     */
641	    private long countOtherOwnersInCity(Owner owner) {
642	        String normalized = normalizeHouseholdField(owner.getCity());
643	        return this.clinicService.findAllOwners().stream()
644	            .filter(existing -> existing.getId() == null || !existing.getId().equals(owner.getId()))
645	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
646	            .count();
647	    }
648	
649	    /**
650	     * The effective registration date to store for a new owner: the date supplied on the request
651	     * when present, otherwise the current server date, in either case rolled forward to a business
652	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
653	     * This single point of resolution is what every registration-date-derived value (the stored
654	     * date, the member id's fiscal-year segment, the per-day create-limit) is computed from.
655	     */
656	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
657	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
658	        return toBusinessDay(date);
659	    }
660	
661	    /**
662	     * The fixed list of public holidays that a registration date must not fall on. A date landing
663	     * on one of these is rolled forward, exactly as weekends are.
664	     */
665	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
666	        LocalDate.of(2026, 1, 1),
667	        LocalDate.of(2026, 1, 26),
668	        LocalDate.of(2026, 4, 25),
669	        LocalDate.of(2026, 12, 25),
670	        LocalDate.of(2026, 12, 28));
671	
672	    /**
673	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
674	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
675	     * unchanged.
676	     */
677	    private static LocalDate toBusinessDay(LocalDate date) {
678	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
679	                || PUBLIC_HOLIDAYS.contains(date)) {
680	            date = date.plusDays(1);
681	        }
682	        return date;
683	    }
684	
685	    /**
686	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
687	     * last name, compared case-insensitively.
688	     */
689	    private int countNamesakes(Owner owner) {
690	        String firstName = normalizeHouseholdField(owner.getFirstName());
691	        String lastName = normalizeHouseholdField(owner.getLastName());
692	        return (int) this.clinicService.findAllOwners().stream()
693	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
694	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
695	            .count();
696	    }
697	
698	    /**
699	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
700	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
701	     * unusually high daily signup volume.
702	     */
703	    private boolean isBulkSignupWarning() {
704	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
705	    }
706	
707	    /** The number of existing owners whose registration date is {@code date}. */
708	    private int countOwnersRegisteredOn(LocalDate date) {
709	        return (int) this.clinicService.findAllOwners().stream()
710	            .filter(existing -> date.equals(existing.getRegistrationDate()))
711	            .count();
712	    }
713	
714	    /**
715	     * The single derived key all duplicate detection flows through: the lower-case hex SHA-256 of
716	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, formed from the
717	     * owner's already-normalized fields (the email is already lower-cased, the telephone already in
718	     * E.164 form, and the last name reduced to its {@link #soundex(String) Soundex} code). Because
719	     * the telephone is part of the key, two owners with the same last name and postcode but
720	     * different telephones resolve to different keys and are both allowed (the later one becoming a
721	     * possible duplicate rather than a hard conflict).
722	     */
723	    private static String identityKey(Owner owner) {
724	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
725	        String email = owner.getEmail() == null ? "" : owner.getEmail();
726	        String key = telephone + "|" + email + "|" + soundex(owner.getLastName());
727	        return Owner.sha256HexLower(key);
728	    }
729	
730	    /**
731	     * Whether {@code owner}'s {@link #identityKey} equals a non-deleted existing owner's, which is
732	     * the sole duplicate condition: the previously separate telephone, email and household checks -
733	     * including the household-duplicate check derived from the {@code householdId} - are now all
734	     * expressed through this one identity key, so only an exact key match is a duplicate and a create
735	     * that trips it is rejected with {@code 409 CONFLICT}. Soft-deleted owners are ignored.
736	     */
737	    private boolean isDuplicate(Owner owner) {
738	        String key = owner.getIdentityKey();
739	        return this.clinicService.findAllOwners().stream()
740	            .filter(existing -> !existing.isDeleted())
741	            .map(Owner::getIdentityKey)
742	            .filter(existing -> existing != null)
743	            .anyMatch(key::equals);
744	    }
745	
746	    /** Common street-type abbreviations expanded during address normalization. */
747	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
748	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
749	
750	    /**
751	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
752	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
753	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
754	     * string when {@code address} is null or blank after normalization.
755	     */
756	    private static String normalizeAddress(String address) {
757	        if (address == null) {
758	            return "";
759	        }
760	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
761	        if (collapsed.isEmpty()) {
762	            return "";
763	        }
764	        StringBuilder sb = new StringBuilder(collapsed.length());
765	        for (String token : collapsed.split(" ")) {
766	            if (sb.length() > 0) {
767	                sb.append(' ');
768	            }
769	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
770	        }
771	        return sb.toString();
772	    }
773	
774	    /**
775	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
776	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
777	     */
778	    private static String normalizeHouseholdField(String value) {
779	        if (value == null) {
780	            return "";
781	        }
782	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
783	    }
784	
785	    /**
786	     * The American Soundex code of {@code value}: the retained first letter followed by up to three
787	     * digits encoding the remaining consonants, right-padded with zeros to length four. Non-letters
788	     * are ignored, adjacent letters coding to the same digit (including when separated by 'H' or 'W')
789	     * are coded once, and vowels (with 'Y') act as separators. Returns the empty string when
790	     * {@code value} holds no letters. Phonetically similar last names share a code, which is what the
791	     * identity key and the possible-duplicate soft match compare on.
792	     */
793	    private static String soundex(String value) {
794	        if (value == null) {
795	            return "";
796	        }
797	        StringBuilder letters = new StringBuilder();
798	        for (char c : value.toCharArray()) {
799	            if (c < 128 && Character.isLetter(c)) {
800	                letters.append(Character.toUpperCase(c));
801	            }
802	        }
803	        if (letters.length() == 0) {
804	            return "";
805	        }
806	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
807	        char previous = soundexDigit(letters.charAt(0));
808	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
809	            char c = letters.charAt(i);
810	            if (c == 'H' || c == 'W') {
811	                continue;
812	            }
813	            char digit = soundexDigit(c);
814	            if (digit != '0' && digit != previous) {
815	                code.append(digit);
816	            }
817	            previous = digit;
818	        }
819	        while (code.length() < 4) {
820	            code.append('0');
821	        }
822	        return code.toString();
823	    }
824	
825	    /** The Soundex digit for an upper-case letter, or {@code '0'} for letters that are not coded. */
826	    private static char soundexDigit(char c) {
827	        switch (c) {
828	            case 'B': case 'F': case 'P': case 'V':
829	                return '1';
830	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
831	                return '2';
832	            case 'D': case 'T':
833	                return '3';
834	            case 'L':
835	                return '4';
836	            case 'M': case 'N':
837	                return '5';
838	            case 'R':
839	                return '6';
840	            default:
841	                return '0';
842	        }
843	    }
844	
845	    /**
846	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
847	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
848	     * key rather than re-derived from the underlying fields here, so the household is described in one
849	     * place and every household-keyed value stays consistent with it.
850	     */
851	    private List<Owner> findHousemates(Owner owner) {
852	        String householdId = householdId(owner);
853	        return this.clinicService.findAllOwners().stream()
854	            .filter(existing -> !existing.isDeleted())
855	            .filter(existing -> householdId(existing).equals(householdId))
856	            .toList();
857	    }
858	
859	    /**
860	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
861	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
862	     */
863	    private int countHouseholdMembers(Owner owner) {
864	        return findHousemates(owner).size() + 1;
865	    }
866	
867	    /**
868	     * The membership level ceiling for a newly registered {@code owner}, derived from the household it
869	     * joins: one above the current maximum {@link Owner#getMembershipLevel() membershipLevel} among the
870	     * existing housemates (owners sharing the same {@code householdId}), so a new owner's reported level
871	     * can never exceed one above the household's current best. Returns {@code null} - meaning no ceiling
872	     * applies - when the owner has no existing household member.
873	     */
874	    private Integer membershipLevelCapForHousehold(Owner owner) {
875	        OptionalInt maxLevel = findHousemates(owner).stream()
876	            .mapToInt(Owner::getMembershipLevel)
877	            .max();
878	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
879	    }
880	
881	    /**
882	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
883	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
884	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
885	     * string standing in for a missing postcode), so housemates always resolve to the same value
886	     * regardless of registration order, and owners sharing a last name and postcode share it
887	     * automatically.
888	     */
889	    private static String householdId(Owner owner) {
890	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
891	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
892	        return Owner.sha256Hex(key).substring(0, 12);
893	    }
894	}
