package org.springframework.samples.petclinic.rest.controller.v1;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Collection;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.OptionalInt;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Function;
import java.util.regex.Pattern;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.mapper.PetMapper;
import org.springframework.samples.petclinic.mapper.VisitMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.model.Pet;
import org.springframework.samples.petclinic.model.Visit;
import org.springframework.samples.petclinic.rest.api.OwnersApi;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.PetDto;
import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
import org.springframework.samples.petclinic.rest.dto.VisitDto;
import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
import org.springframework.samples.petclinic.service.ClinicService;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.context.request.RequestContextHolder;
import org.springframework.web.context.request.ServletRequestAttributes;
import org.springframework.web.util.UriComponentsBuilder;

import jakarta.transaction.Transactional;

/**
 * @author Vitaliy Fedoriv
 */

@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV1 implements OwnersApi {

    /** Dedicated audit logger; a successful create emits one line here. */
    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    /** Dedicated notification logger; a successful create enqueues one welcome line here. */
    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");

    /** Monotonically increasing sequence number stamped onto each structured {@link OwnerCreatedEvent}. */
    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
        new java.util.concurrent.atomic.AtomicLong();

    /** Request header carrying the client-supplied key that makes a create idempotent. */
    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";

    /**
     * Idempotency-Key -> id of the owner originally created under that key. A repeat create carrying an
     * already-seen key returns that owner rather than creating a duplicate. Only successful creates are
     * recorded here, and the key space is client-supplied, so the map is bounded by distinct keys seen.
     */
    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();

    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");

    /** Disposable email domains that are not accepted for an owner's email; a create with one is rejected. */
    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
        "mailinator.com", "tempmail.com", "guerrillamail.com");

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        return withOwner(ownerId, owner ->
            new ResponseEntity<>(buildOwnerDto(owner), HttpStatus.OK));
    }

    /**
     * Look up the owner identified by {@code ownerId} and, when it exists, produce the response with
     * {@code onFound}; when no such owner exists, short-circuit with {@code 404 NOT_FOUND}. Centralizes
     * the fetch-and-guard shared by the single-owner endpoints so it is written once, not copied.
     */
    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> onFound) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return onFound.apply(owner);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
        String idempotencyKey = currentIdempotencyKey();
        if (idempotencyKey != null) {
            Integer existingId = idempotentCreates.get(idempotencyKey);
            if (existingId != null) {
                Owner existing = this.clinicService.findOwnerById(existingId);
                if (existing != null) {
                    return new ResponseEntity<>(buildOwnerDto(existing), HttpStatus.OK);
                }
            }
        }
        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
                && response.getBody() != null && response.getBody().getId() != null) {
            idempotentCreates.put(idempotencyKey, response.getBody().getId());
        }
        return response;
    }

    /**
     * The non-blank {@code Idempotency-Key} header on the current request, or {@code null} when the
     * header is absent or blank. Read from the ambient request rather than the handler signature so the
     * generated {@link OwnersApi#addOwner} contract stays unchanged.
     */
    private static String currentIdempotencyKey() {
        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs) {
            String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
            if (key != null && !key.isBlank()) {
                return key;
            }
        }
        return null;
    }

    /**
     * Run the create pipeline for a new owner from its submitted fields and return the response: the
     * fields are mapped, normalized and validated, the registration date is resolved, the per-day,
     * identity and per-city gates are applied, the derived registration attributes are
     * assigned and the owner is saved and audited, yielding {@code 201 CREATED} with the new owner and
     * its {@code Location}. A gate that trips short-circuits with its own status ({@code 400},
     * {@code 429} or {@code 409}) and no owner is created. This is the single place an owner is created;
     * {@link #addOwner} is the thin entry point that delegates here, so request-level concerns stay out
     * of the create pipeline.
     */
    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        if (!normalizeAndValidateFields(owner)) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
        owner.setRegistrationDate(registrationDate);
        if (countOwnersRegisteredOn(registrationDate) >= 100) {
            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
        }
        owner.setHouseholdId(householdId(owner));
        owner.setIdentityKey(identityKey(owner));
        if (isDuplicate(owner)) {
            return new ResponseEntity<>(HttpStatus.CONFLICT);
        }
        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
        if (countOwnersInCity(owner.getCity()) >= 50) {
            return new ResponseEntity<>(HttpStatus.CONFLICT);
        }
        assignRegistrationAttributes(owner, sharesHousehold);
        this.clinicService.saveOwner(owner);
        auditOwnerCreated(owner);
        enqueueWelcomeNotification(owner);
        HttpHeaders headers = new HttpHeaders();
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
    }

    /**
     * Emit the audit trail for a freshly persisted {@code owner} on the dedicated {@code AUDIT}
     * logger: the human-readable line followed by the structured {@link OwnerCreatedEvent}. This is
     * the one place a created owner's identifiers are read for the audit trail, so a change to which
     * identifier is audited is confined here rather than woven through the create pipeline.
     */
    private void auditOwnerCreated(Owner owner) {
        AUDIT.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
        AUDIT.info(OwnerCreatedEvent.of(AUDIT_EVENT_SEQ.incrementAndGet(), owner).toJson());
    }

    /**
     * Enqueue the welcome notification for a freshly persisted {@code owner} on the dedicated
     * {@code NOTIFY} logger: one line carrying the owner's id and member id, the identifiers a
     * downstream notifier needs to greet the new member. Kept separate from the audit trail so the
     * notification concern is emitted in one place, after the owner is saved and its id is assigned.
     */
    private void enqueueWelcomeNotification(Owner owner) {
        NOTIFY.info("Welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
    }

    /**
     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
     * and validate them, returning whether the owner may proceed to creation. On success the owner's
     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
     */
    private boolean normalizeAndValidateFields(Owner owner) {
        if (!normalizeAddressFields(owner)) {
            return false;
        }
        if (owner.getEmail() != null) {
            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
            if (!EMAIL_PATTERN.matcher(email).matches()) {
                return false;
            }
            if (isDisposableEmailDomain(email)) {
                return false;
            }
            owner.setEmail(email);
        }
        if (!isPostcodeValidForCity(owner)) {
            return false;
        }
        String telephone = normalizeTelephone(owner.getTelephone());
        if (telephone == null) {
            return false;
        }
        owner.setTelephone(telephone);
        return true;
    }

    /**
     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
     * returning whether the owner may proceed to creation. The structured fields are preferred when
     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
     * composed value (the normalized addressLine1, with a single space and the normalized
     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
     * address. This is the single place the owner's address is read, canonicalized and written back,
     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
     */
    private boolean normalizeAddressFields(Owner owner) {
        String line1 = normalizeAddress(owner.getAddressLine1());
        if (!line1.isEmpty()) {
            String line2 = normalizeAddress(owner.getAddressLine2());
            owner.setAddressLine1(line1);
            owner.setAddressLine2(line2.isEmpty() ? null : line2);
            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
            return true;
        }
        String address = normalizeAddress(owner.getAddress());
        if (address.isEmpty()) {
            return false;
        }
        owner.setAddress(address);
        return true;
    }

    /**
     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
     */
    private static boolean isDisposableEmailDomain(String email) {
        int at = email.lastIndexOf('@');
        if (at < 0) {
            return false;
        }
        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
    }

    /**
     * Build the response DTO for a single owner, attaching the per-response derived flags that are
     * computed against the owner population rather than carried on the owner itself (currently the
     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
     * listing intentionally omits these flags.
     */
    private OwnerDto buildOwnerDto(Owner owner) {
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
        ownerDto.setCapacityWarning(isCapacityWarning(owner));
        return ownerDto;
    }

    /**
     * Whether {@code owner}'s city is approaching its per-city capacity limit: it already holds between
     * 40 and 49 other owners, one short of the hard limit of 50 at which creation is rejected.
     * Surfaced on responses as {@code capacityWarning}. Computed against the current owner population
     * excluding this owner, so the count basis mirrors the per-city create gate (which counts the
     * owners already present, before the new one is added).
     */
    private boolean isCapacityWarning(Owner owner) {
        long othersInCity = countOtherOwnersInCity(owner);
        return othersInCity >= 40 && othersInCity < 50;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        currentOwner.setAddress(ownerFieldsDto.getAddress());
        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
        String email = ownerFieldsDto.getEmail();
        if (email != null) {
            email = email.trim().toLowerCase(Locale.ROOT);
            if (!EMAIL_PATTERN.matcher(email).matches()) {
                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
            }
        }
        currentOwner.setEmail(email);
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        return withOwner(ownerId, owner -> {
            owner.setDeleted(true);
            this.clinicService.saveOwner(owner);
            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
        });
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

