303	    /** The membership points derived from the given factors: they start at 0, add 2 when
304	     *  {@code email} is present, add 1 when {@code namesakeCount} is 0, add 2 for a household of 3 or
305	     *  more ({@code householdMemberCount}), and add 3 for sufficient tenure (see
306	     *  {@link #hasTenureBonus(LocalDate)}). */
307	    private static int membershipPoints(String email, Integer namesakeCount,
308	            Integer householdMemberCount, LocalDate registrationDate) {
309	        int points = 0;
310	        if (email != null && !email.isBlank()) {
311	            points += 2;
312	        }
313	        if (namesakeCount != null && namesakeCount == 0) {
314	            points += 1;
315	        }
316	        if (householdMemberCount != null && householdMemberCount >= 3) {
317	            points += 2;
318	        }
319	        if (hasTenureBonus(registrationDate)) {
320	            points += 3;
321	        }
322	        return points;
