325	    /** Whether the owner's tenure earns the membership tenure bonus: the elapsed fiscal years from
326	     *  {@code registrationDate} to today exceed one, i.e. the registration falls two or more fiscal
327	     *  years before the current one (fiscal years start 1 July). A null registration date earns no
328	     *  bonus. */
329	    private static boolean hasTenureBonus(LocalDate registrationDate) {
330	        return registrationDate != null
331	            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
332	    }
