336	     * in which that fiscal year ends: a date in July-December belongs to the fiscal year ending the
337	     * following calendar year, and a date in January-June to the fiscal year ending that same year
338	     * (e.g. 2026-09-05 -> 2027, 2026-03-01 -> 2026).
339	     */
340	    public static int fiscalYear(LocalDate date) {
341	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
342	    }
