package org.springframework.samples.petclinic.rest.controller.v1;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Collection;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.OptionalInt;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Function;
import java.util.regex.Pattern;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.mapper.PetMapper;
import org.springframework.samples.petclinic.mapper.VisitMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.model.Pet;
import org.springframework.samples.petclinic.model.Visit;
import org.springframework.samples.petclinic.rest.api.OwnersApi;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.PetDto;
import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
import org.springframework.samples.petclinic.rest.dto.VisitDto;
import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
import org.springframework.samples.petclinic.service.ClinicService;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.context.request.RequestContextHolder;
import org.springframework.web.context.request.ServletRequestAttributes;
import org.springframework.web.util.UriComponentsBuilder;

import jakarta.transaction.Transactional;

/**
 * @author Vitaliy Fedoriv
 */

@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV1 implements OwnersApi {

    /** Dedicated audit logger; a successful create emits one line here. */
    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    /** Dedicated notification logger; a successful create enqueues one welcome line here. */
    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");

    /** Monotonically increasing sequence number stamped onto each structured {@link OwnerCreatedEvent}. */
    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
        new java.util.concurrent.atomic.AtomicLong();

    /** Request header carrying the client-supplied key that makes a create idempotent. */
    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";

    /**
     * Idempotency-Key -> id of the owner originally created under that key. A repeat create carrying an
     * already-seen key returns that owner rather than creating a duplicate. Only successful creates are
     * recorded here, and the key space is client-supplied, so the map is bounded by distinct keys seen.
     */
    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();

    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");

    /** Disposable email domains that are not accepted for an owner's email; a create with one is rejected. */
    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
        "mailinator.com", "tempmail.com", "guerrillamail.com");

    /**
     * Hard per-city capacity: a create into a city that already holds this many owners is rejected
     * with {@code 409 CONFLICT}. Counted against the owners already present, before the new one is
     * added, matching the basis of {@link #countOwnersInCity(String)}.
     */
    private static final int CITY_HARD_CAPACITY = 50;

    /**
     * Soft per-city capacity: the threshold, one band below the {@link #CITY_HARD_CAPACITY hard
     * limit}, at which a city is treated as filling up. Counted against the owners already present
     * excluding the owner itself; surfaced on responses as {@code capacityWarning} for the band
     * between this soft threshold and the hard limit.
     */
    private static final int CITY_SOFT_CAPACITY = 40;

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        return withOwner(ownerId, owner ->
            new ResponseEntity<>(buildOwnerDto(owner), HttpStatus.OK));
    }

    /**
     * Look up the owner identified by {@code ownerId} and, when it exists, produce the response with
     * {@code onFound}; when no such owner exists, short-circuit with {@code 404 NOT_FOUND}. Centralizes
     * the fetch-and-guard shared by the single-owner endpoints so it is written once, not copied.
     */
    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> onFound) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return onFound.apply(owner);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
        String idempotencyKey = currentIdempotencyKey();
        if (idempotencyKey != null) {
            Integer existingId = idempotentCreates.get(idempotencyKey);
            if (existingId != null) {
                Owner existing = this.clinicService.findOwnerById(existingId);
                if (existing != null) {
                    return new ResponseEntity<>(buildOwnerDto(existing), HttpStatus.OK);
                }
            }
        }
        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
                && response.getBody() != null && response.getBody().getId() != null) {
            idempotentCreates.put(idempotencyKey, response.getBody().getId());
        }
        return response;
    }

    /**
     * The non-blank {@code Idempotency-Key} header on the current request, or {@code null} when the
     * header is absent or blank. Read from the ambient request rather than the handler signature so the
     * generated {@link OwnersApi#addOwner} contract stays unchanged.
     */
    private static String currentIdempotencyKey() {
        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs) {
            String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
            if (key != null && !key.isBlank()) {
                return key;
            }
        }
        return null;
    }

    /**
     * Run the create pipeline for a new owner from its submitted fields and return the response: the
     * fields are mapped, normalized and validated, the registration date is resolved, the per-day,
     * identity and per-city gates are applied, the derived registration attributes are
     * assigned and the owner is saved and audited, yielding {@code 201 CREATED} with the new owner and
     * its {@code Location}. A gate that trips short-circuits with its own status ({@code 400},
     * {@code 429} or {@code 409}) and no owner is created. This is the single place an owner is created;
     * {@link #addOwner} is the thin entry point that delegates here, so request-level concerns stay out
     * of the create pipeline.
     */
    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        if (!normalizeAndValidateFields(owner)) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
        owner.setRegistrationDate(registrationDate);
        if (countOwnersRegisteredOn(registrationDate) >= 100) {
            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
        }
        owner.setHouseholdId(householdId(owner));
        owner.setIdentityKey(identityKey(owner));
        if (isDuplicate(owner)) {
            return new ResponseEntity<>(HttpStatus.CONFLICT);
        }
        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
        if (countOwnersInCity(owner.getCity()) >= CITY_HARD_CAPACITY) {
            return new ResponseEntity<>(HttpStatus.CONFLICT);
        }
        assignRegistrationAttributes(owner, sharesHousehold);
        this.clinicService.saveOwner(owner);
        auditOwnerCreated(owner);
        enqueueWelcomeNotification(owner);
        HttpHeaders headers = new HttpHeaders();
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
    }

    /**
     * Emit the audit trail for a freshly persisted {@code owner} on the dedicated {@code AUDIT}
     * logger: the human-readable line followed by the structured {@link OwnerCreatedEvent}. This is
     * the one place a created owner's identifiers are read for the audit trail, so a change to which
     * identifier is audited is confined here rather than woven through the create pipeline.
     */
    private void auditOwnerCreated(Owner owner) {
        AUDIT.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
        AUDIT.info(OwnerCreatedEvent.of(AUDIT_EVENT_SEQ.incrementAndGet(), owner).toJson());
    }

    /**
     * Enqueue the welcome notification for a freshly persisted {@code owner} on the dedicated
     * {@code NOTIFY} logger: one line carrying the owner's id and member id, the identifiers a
     * downstream notifier needs to greet the new member. Kept separate from the audit trail so the
     * notification concern is emitted in one place, after the owner is saved and its id is assigned.
     */
    private void enqueueWelcomeNotification(Owner owner) {
        NOTIFY.info("Welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
    }

    /**
     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
     * and validate them, returning whether the owner may proceed to creation. On success the owner's
     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
     */
    private boolean normalizeAndValidateFields(Owner owner) {
        if (!normalizeAddressFields(owner)) {
            return false;
        }
        if (owner.getEmail() != null) {
            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
            if (!EMAIL_PATTERN.matcher(email).matches()) {
                return false;
            }
            if (isDisposableEmailDomain(email)) {
                return false;
            }
            owner.setEmail(email);
        }
        if (!isPostcodeValidForCity(owner)) {
            return false;
        }
        String telephone = normalizeTelephone(owner.getTelephone());
        if (telephone == null) {
            return false;
        }
        owner.setTelephone(telephone);
        return true;
    }

    /**
     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
     * returning whether the owner may proceed to creation. The structured fields are preferred when
     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
     * composed value (the normalized addressLine1, with a single space and the normalized
     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
     * address. This is the single place the owner's address is read, canonicalized and written back,
     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
     */
    private boolean normalizeAddressFields(Owner owner) {
        String line1 = normalizeAddress(owner.getAddressLine1());
        if (!line1.isEmpty()) {
            String line2 = normalizeAddress(owner.getAddressLine2());
            owner.setAddressLine1(line1);
            owner.setAddressLine2(line2.isEmpty() ? null : line2);
            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
            return true;
        }
        String address = normalizeAddress(owner.getAddress());
        if (address.isEmpty()) {
            return false;
        }
        owner.setAddress(address);
        return true;
    }

    /**
     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
     */
    private static boolean isDisposableEmailDomain(String email) {
        int at = email.lastIndexOf('@');
        if (at < 0) {
            return false;
        }
        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
    }

    /**
     * Build the response DTO for a single owner, attaching the per-response derived flags that are
     * computed against the owner population rather than carried on the owner itself (currently the
     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
     * listing intentionally omits these flags.
     */
    private OwnerDto buildOwnerDto(Owner owner) {
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
        ownerDto.setCapacityWarning(isCapacityWarning(owner));
        return ownerDto;
    }

    /**
     * Whether {@code owner}'s city is approaching its per-city capacity limit: it already holds between
     * 40 and 49 other owners, one short of the hard limit of 50 at which creation is rejected.
     * Surfaced on responses as {@code capacityWarning}. Computed against the current owner population
     * excluding this owner, so the count basis mirrors the per-city create gate (which counts the
     * owners already present, before the new one is added).
     */
    private boolean isCapacityWarning(Owner owner) {
        long othersInCity = countOtherOwnersInCity(owner);
        return othersInCity >= 40 && othersInCity < 50;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        currentOwner.setAddress(ownerFieldsDto.getAddress());
        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
        String email = ownerFieldsDto.getEmail();
        if (email != null) {
            email = email.trim().toLowerCase(Locale.ROOT);
            if (!EMAIL_PATTERN.matcher(email).matches()) {
                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
            }
        }
        currentOwner.setEmail(email);
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        return withOwner(ownerId, owner -> {
            owner.setDeleted(true);
            this.clinicService.saveOwner(owner);
            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
        });
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Visit visit = visitMapper.toVisit(visitFieldsDto);
        Pet pet = new Pet();
        pet.setId(petId);
        visit.setPet(pet);
        this.clinicService.saveVisit(visit);
        VisitDto visitDto = visitMapper.toVisitDto(visit);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    /** Matches a well-formed postcode: exactly 4 digits. */
    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");

    /**
     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
     */
    private static boolean isPostcodeValidForCity(Owner owner) {
        String postcode = owner.getPostcode();
        if (postcode == null) {
            return true;
        }
        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
            return false;
        }
        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
        if (range == null) {
            return true;
        }
        int value = Integer.parseInt(postcode);
        return value >= range[0] && value <= range[1];
    }

    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");

    /**
     * Canonical stored form of a telephone number in E.164: a leading '+' and country
     * code are kept when present; otherwise country code '+61' is assumed and a single
     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
     * Returns {@code null} when the number cannot form a valid E.164 value.
     */
    private static String normalizeTelephone(String telephone) {
        if (telephone == null) {
            return null;
        }
        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
        String e164;
        if (cleaned.startsWith("+")) {
            e164 = cleaned;
        } else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            e164 = "+61" + national;
        }
        if (!E164_PATTERN.matcher(e164).matches()) {
            return null;
        }
        return hasValidNationalNumberLength(e164) ? e164 : null;
    }

    /**
     * Whether the national number of a well-formed E.164 value has the length required for its
     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
     */
    private static boolean hasValidNationalNumberLength(String e164) {
        String countryCode = Owner.countryCodeOf(e164);
        if (countryCode == null) {
            return true;
        }
        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
    }

    /**
     * Compute and assign the derived attributes carried by a newly registered owner: the member id,
     * household id, namesake count and household member count. Each is derived from the owner's
     * already-normalized fields and the existing owner population, so this must run before the owner
     * is saved, while the counts still exclude the owner being created.
     *
     * <p>{@code declaredMember} is true when the owner was created into an existing household by
     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
     * runs (and, since a create that reaches here shares no existing household, does not flag it).
     */
    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
        owner.setMemberId(generateMemberId(owner));
        owner.setHouseholdId(householdId(owner));
        owner.setNamesakeCount(countNamesakes(owner));
        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
        owner.setMembershipLevelCap(membershipLevelCapForHousehold(owner));
        if (declaredMember) {
            owner.setPossibleDuplicate(false);
            owner.setPossibleDuplicateOf(null);
        } else {
            assignPossibleDuplicate(owner);
        }
    }

    /**
     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's postcode
     * and last-name {@link #soundex(String) Soundex} yet resolves to a different {@link #identityKey}.
     * Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf} to the
     * matching owner's id. Runs before save, against the existing owner population.
     */
    private void assignPossibleDuplicate(Owner owner) {
        Integer matchId = findPossibleDuplicateOf(owner);
        owner.setPossibleDuplicate(matchId != null);
        owner.setPossibleDuplicateOf(matchId);
    }

    /**
     * The id of an existing owner that shares {@code owner}'s postcode and last-name
     * {@link #soundex(String) Soundex} but resolves to a different {@link #identityKey}, or
     * {@code null} when there is none. Because the telephone is part of the identity key, two owners
     * with the same last name and postcode but different telephones differ in key and so match here,
     * making the later a soft (possible) duplicate rather than a hard conflict. When several match,
     * the lowest id is returned. An owner without a postcode never matches.
     */
    private Integer findPossibleDuplicateOf(Owner owner) {
        String postcode = owner.getPostcode();
        if (postcode == null) {
            return null;
        }
        String soundex = soundex(owner.getLastName());
        String identityKey = owner.getIdentityKey();
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> !existing.isDeleted())
            .filter(existing -> existing.getId() != null
                && postcode.equals(existing.getPostcode())
                && soundex(existing.getLastName()).equals(soundex)
                && !identityKey.equals(existing.getIdentityKey()))
            .map(Owner::getId)
            .min(Integer::compareTo)
            .orElse(null);
    }

    /**
     * Build {@code owner}'s member id '<REGION><FY><HASH8><CHK>': REGION is the region code derived
     * from the owner's postcode ({@link Owner#getRegion()}), FY the two-digit
     * {@link Owner#fiscalYearSegment(LocalDate) fiscal-year segment} of the business-day-adjusted
     * {@link Owner#getRegistrationDate() registration date}, HASH8 the first 8 upper-case hex
     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
     * owner's last name, and CHK a single {@link Owner#luhnCheckDigit(String) Luhn check digit} over
     * the digits of '<REGION><FY><HASH8>' (e.g. 'NSW271A2B3C4D5'). The identity is otherwise a pure
     * function of the region, fiscal year and the (telephone, last name) pair; only when the computed
     * id collides with an existing owner's member id is it de-duplicated by appending '-<n>' with the
     * smallest {@code n} of 2 or more that makes it unique (e.g. 'NSW271A2B3C4D5-2').
     */
    private String generateMemberId(Owner owner) {
        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
        String hash8 = Owner.sha256Hex(telephone + lastName).substring(0, 8);
        String core = owner.getRegion() + Owner.fiscalYearSegment(owner.getRegistrationDate()) + hash8;
        String base = core + Owner.luhnCheckDigit(core);
        return deduplicateMemberId(base);
    }

    /**
     * De-duplicate a computed member id against the existing owner population: when {@code base}
     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
     * {@code n} of 2 or more that yields an id no existing owner carries.
     */
    private String deduplicateMemberId(String base) {
        Set<String> existing = this.clinicService.findAllOwners().stream()
            .map(Owner::getMemberId)
            .filter(code -> code != null)
            .collect(java.util.stream.Collectors.toSet());
        if (!existing.contains(base)) {
            return base;
        }
        int n = 2;
        while (existing.contains(base + "-" + n)) {
            n++;
        }
        return base + "-" + n;
    }

    /**
     * The number of existing owners registered in {@code city}, compared case-insensitively
     * with collapsed whitespace.
     */
    private int countOwnersInCity(String city) {
        String normalized = normalizeHouseholdField(city);
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
            .count();
    }

    /**
     * The number of existing owners in {@code owner}'s city other than {@code owner} itself, compared
     * case-insensitively with collapsed whitespace. This is the count of owners already present in the
     * city that a newly created owner joins, mirroring the basis of the per-city create gate.
     */
    private long countOtherOwnersInCity(Owner owner) {
        String normalized = normalizeHouseholdField(owner.getCity());
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> existing.getId() == null || !existing.getId().equals(owner.getId()))
            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
            .count();
    }

    /**
     * The effective registration date to store for a new owner: the date supplied on the request
     * when present, otherwise the current server date, in either case rolled forward to a business
     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
     * This single point of resolution is what every registration-date-derived value (the stored
     * date, the member id's fiscal-year segment, the per-day create-limit) is computed from.
     */
    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
        return toBusinessDay(date);
    }

    /**
     * The fixed list of public holidays that a registration date must not fall on. A date landing
     * on one of these is rolled forward, exactly as weekends are.
     */
    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
        LocalDate.of(2026, 1, 1),
        LocalDate.of(2026, 1, 26),
        LocalDate.of(2026, 4, 25),
        LocalDate.of(2026, 12, 25),
        LocalDate.of(2026, 12, 28));

    /**
     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
     * unchanged.
     */
    private static LocalDate toBusinessDay(LocalDate date) {
        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
                || PUBLIC_HOLIDAYS.contains(date)) {
            date = date.plusDays(1);
        }
        return date;
    }

    /**
     * The number of existing owners (before this create) sharing {@code owner}'s first name and
     * last name, compared case-insensitively.
     */
    private int countNamesakes(Owner owner) {
        String firstName = normalizeHouseholdField(owner.getFirstName());
        String lastName = normalizeHouseholdField(owner.getLastName());
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
            .count();
    }

    /**
     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
     * unusually high daily signup volume.
     */
    private boolean isBulkSignupWarning() {
        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
    }

    /** The number of existing owners whose registration date is {@code date}. */
    private int countOwnersRegisteredOn(LocalDate date) {
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> date.equals(existing.getRegistrationDate()))
            .count();
    }

    /**
     * The single derived key all duplicate detection flows through: the lower-case hex SHA-256 of
     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, formed from the
     * owner's already-normalized fields (the email is already lower-cased, the telephone already in
     * E.164 form, and the last name reduced to its {@link #soundex(String) Soundex} code). Because
     * the telephone is part of the key, two owners with the same last name and postcode but
     * different telephones resolve to different keys and are both allowed (the later one becoming a
     * possible duplicate rather than a hard conflict).
     */
    private static String identityKey(Owner owner) {
        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
        String email = owner.getEmail() == null ? "" : owner.getEmail();
        String key = telephone + "|" + email + "|" + soundex(owner.getLastName());
        return Owner.sha256HexLower(key);
    }

    /**
     * Whether {@code owner}'s {@link #identityKey} equals a non-deleted existing owner's, which is
     * the sole duplicate condition: the previously separate telephone, email and household checks -
     * including the household-duplicate check derived from the {@code householdId} - are now all
     * expressed through this one identity key, so only an exact key match is a duplicate and a create
     * that trips it is rejected with {@code 409 CONFLICT}. Soft-deleted owners are ignored.
     */
    private boolean isDuplicate(Owner owner) {
        String key = owner.getIdentityKey();
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> !existing.isDeleted())
            .map(Owner::getIdentityKey)
            .filter(existing -> existing != null)
            .anyMatch(key::equals);
    }

    /** Common street-type abbreviations expanded during address normalization. */
    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    /**
     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
     * string when {@code address} is null or blank after normalization.
     */
    private static String normalizeAddress(String address) {
        if (address == null) {
            return "";
        }
        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (String token : collapsed.split(" ")) {
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
        }
        return sb.toString();
    }

    /**
     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
     */
    private static String normalizeHouseholdField(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /**
     * The American Soundex code of {@code value}: the retained first letter followed by up to three
     * digits encoding the remaining consonants, right-padded with zeros to length four. Non-letters
     * are ignored, adjacent letters coding to the same digit (including when separated by 'H' or 'W')
     * are coded once, and vowels (with 'Y') act as separators. Returns the empty string when
     * {@code value} holds no letters. Phonetically similar last names share a code, which is what the
     * identity key and the possible-duplicate soft match compare on.
     */
    private static String soundex(String value) {
        if (value == null) {
            return "";
        }
        StringBuilder letters = new StringBuilder();
        for (char c : value.toCharArray()) {
            if (c < 128 && Character.isLetter(c)) {
                letters.append(Character.toUpperCase(c));
            }
        }
        if (letters.length() == 0) {
            return "";
        }
        StringBuilder code = new StringBuilder().append(letters.charAt(0));
        char previous = soundexDigit(letters.charAt(0));
        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
            char c = letters.charAt(i);
            if (c == 'H' || c == 'W') {
                continue;
            }
            char digit = soundexDigit(c);
            if (digit != '0' && digit != previous) {
                code.append(digit);
            }
            previous = digit;
        }
        while (code.length() < 4) {
            code.append('0');
        }
        return code.toString();
    }

    /** The Soundex digit for an upper-case letter, or {@code '0'} for letters that are not coded. */
    private static char soundexDigit(char c) {
        switch (c) {
            case 'B': case 'F': case 'P': case 'V':
                return '1';
            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
                return '2';
            case 'D': case 'T':
                return '3';
            case 'L':
                return '4';
            case 'M': case 'N':
                return '5';
            case 'R':
                return '6';
            default:
                return '0';
        }
    }

    /**
     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
     * key rather than re-derived from the underlying fields here, so the household is described in one
     * place and every household-keyed value stays consistent with it.
     */
    private List<Owner> findHousemates(Owner owner) {
        String householdId = householdId(owner);
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> !existing.isDeleted())
            .filter(existing -> householdId(existing).equals(householdId))
            .toList();
    }

    /**
     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
     */
    private int countHouseholdMembers(Owner owner) {
        return findHousemates(owner).size() + 1;
    }

    /**
     * The membership level ceiling for a newly registered {@code owner}, derived from the household it
     * joins: one above the current maximum {@link Owner#getMembershipLevel() membershipLevel} among the
     * existing housemates (owners sharing the same {@code householdId}), so a new owner's reported level
     * can never exceed one above the household's current best. Returns {@code null} - meaning no ceiling
     * applies - when the owner has no existing household member.
     */
    private Integer membershipLevelCapForHousehold(Owner owner) {
        OptionalInt maxLevel = findHousemates(owner).stream()
            .mapToInt(Owner::getMembershipLevel)
            .max();
        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
    }

    /**
     * A stable identifier shared by every owner in the same household, i.e. every owner with the
     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
     * string standing in for a missing postcode), so housemates always resolve to the same value
     * regardless of registration order, and owners sharing a last name and postcode share it
     * automatically.
     */
    private static String householdId(Owner owner) {
        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
        return Owner.sha256Hex(key).substring(0, 12);
    }
}

